// Small read-only pilot export; shared native acceptance helpers.
#define main lwkm_acceptance_main
#include "../metaswap_hru/accept_metaswap.cpp"
#undef main
void put(const fs::path&p,const std::string&s){std::ofstream f(p,std::ios::binary);f<<s;f.close();check(bool(f),"Write failed: "+p.string());}
void datecheck(const std::string&s){check(s.size()==8,"Date must be YYYYMMDD");int y=integer(s.substr(0,4)),m=integer(s.substr(4,2)),d=integer(s.substr(6,2));check(y>=1900&&y<=2200&&m>=1&&m<=12,"Invalid date");check(d==10||d==20||d==monthdays(y,m),"Not a calendar decade end");}
int main(int argc,char**argv){try{
 check(argc==6,"Usage: export_hru21.exe SOURCE NEW_DEST PILOT_CSV FIRST LAST");
 fs::path src=fs::u8path(argv[1]),dst=fs::u8path(argv[2]),pilot=fs::u8path(argv[3]);std::string first=argv[4],last=argv[5];datecheck(first);datecheck(last);check(first<=last,"Reversed dates");
 check(!fs::exists(dst),"Destination already exists; choose a new directory");
 auto identity=text(src/"run_identity.txt");check(identity.rfind("LWKM-MSW-HRU-1.0.0",0)==0,"Unsupported producer");auto ik=kv(identity);for(auto k:{"exe","area","mapping","sources"})check(digest(ik[k]),"Invalid run identity");check(ik["units"]=="m3/m2_per_decade;factor=1000;sign=source;missing=blank_strict_support","Unknown units contract");
 std::string line;std::set<int> selected,population;std::istringstream pp(text(pilot));std::getline(pp,line);check(csv(line)[0]=="hru_id","Invalid pilot header");while(std::getline(pp,line)){if(line.empty())continue;auto r=csv(line);check(selected.insert(integer(r[0])).second,"Duplicate pilot HRU");}check(selected.size()==21,"Expected exactly 21 pilot HRUs");
 auto support=text(src/"hru_support.csv");std::istringstream sp(support);std::getline(sp,line);check(csv(line)==std::vector<std::string>({"hru_id","svats","area_m2"}),"Unknown support header");std::string sub=line+"\n";while(std::getline(sp,line)){if(line.empty())continue;auto r=csv(line);check(r.size()==3,"Invalid support");int id=integer(r[0]);check(id>0&&population.insert(id).second&&integer(r[1])>0&&real(r[2])>0,"Invalid/duplicate support HRU");if(selected.count(id))sub+=line+"\n";}for(int id:selected)check(population.count(id),"Pilot HRU absent from support");
 fs::create_directories(dst/"reference");fs::create_directories(dst/"source_markers");put(dst/"pilot-hrus.csv",text(pilot));put(dst/"source_hru_support.csv",support);put(dst/"source_run_identity.txt",identity);put(dst/"reference/hru_support.csv",sub);
 std::vector<std::string> expected={"hru_id","days","complete"};for(auto&n:names)expected.push_back(n);for(int j=0;j<9;++j)expected.push_back("coverage_"+names[j]);
 std::ofstream combined(dst/"HRU21_reference.csv",std::ios::binary),manifest(dst/"source_manifest.csv");manifest<<"decade_end,source_csv_sha256,source_marker_sha256,source_qc_sha256,selected_csv_sha256,incomplete_selected\n";size_t periods=0,incomplete=0;
 for(std::string d=first;d<=last;d=next(d)){
 auto source=src/(d+".csv"),mark=src/(d+".sha256"),qc=src/(d+"_qc.csv");auto marker=text(mark);check(marker.rfind(identity,0)==0,"Mixed run identity: "+d);auto mk=kv(marker);check(mk["date"]==d&&digest(mk["output"])&&digest(mk["qc"]),"Invalid marker: "+d);check(hash(source)==mk["output"],"CSV hash mismatch: "+d);check(hash(qc)==mk["qc"],"QC hash mismatch: "+d);
 std::set<std::string> raster;std::istringstream mi(marker);while(std::getline(mi,line)){auto r=csv(line);if(r.size()==4&&std::find(names.begin(),names.begin()+9,r[0])!=names.begin()+9){check(raster.insert(r[0]).second&&digest(r[3])&&!r[2].empty()&&r[2].find_first_not_of("0123456789")==std::string::npos,"Invalid raster marker");}}check(raster.size()==9,"Missing raster provenance");
 std::istringstream f(text(source));std::getline(f,line);check(csv(line)==expected,"Unknown CSV schema: "+d);if(!periods)combined<<"decade_end,"<<line<<"\n";std::string subset=line+"\n";std::set<int> seen;int bad=0;int days=integer(d.substr(6,2));days=days<=20?10:days-20;
 while(std::getline(f,line)){if(line.empty())continue;auto r=csv(line);check(r.size()==27,"Wrong column count: "+d);int id=integer(r[0]);check(population.count(id)&&seen.insert(id).second,"Unknown/duplicate HRU: "+d);check(integer(r[1])==days,"Wrong decade length: "+d);bool full=true;for(int j=0;j<15;++j)if(!r[3+j].empty())real(r[3+j]);for(int j=0;j<9;++j){double c=real(r[18+j]);check(c>=0&&c<=1,"Invalid coverage");bool valid=!r[3+j].empty();check(valid==(c==1),"Coverage/value mismatch");full=full&&valid;}check(integer(r[2])==int(full),"Complete flag mismatch");
 if(selected.count(id)){subset+=line+"\n";combined<<d<<","<<line<<"\n";if(!full)++bad;}}
 check(seen==population,"Missing population HRUs: "+d);check(hash(source)==mk["output"]&&text(mark)==marker&&hash(qc)==mk["qc"],"Source changed during export: "+d);
 put(dst/"reference"/(d+".csv"),subset);auto sh=hash(dst/"reference"/(d+".csv"));put(dst/"reference"/(d+".sha256"),"output="+sh+"\nparent_output="+mk["output"]+"\n");put(dst/"source_markers"/(d+".sha256"),marker);put(dst/"source_markers"/(d+"_qc.csv"),text(qc));manifest<<d<<","<<mk["output"]<<","<<hash(mark)<<","<<mk["qc"]<<","<<sh<<","<<bad<<"\n";incomplete+=bad;++periods;if(periods%36==0)std::cout<<d<<" verified, periods="<<periods<<std::endl;
 }
 combined.close();manifest.close();check(bool(combined)&&bool(manifest),"Final write failed");check(text(src/"run_identity.txt")==identity&&text(src/"hru_support.csv")==support,"Run/support changed during export");
 put(dst/"export_status.txt","version=1.0.0\nfirst="+first+"\nlast="+last+"\ndecades="+std::to_string(periods)+"\nselected_hrus=21\nsource_hrus="+std::to_string(population.size())+"\nincomplete_selected="+std::to_string(incomplete)+"\nraw_signs_preserved=true\nproduction_admitted=false\nraster_sources_rehashed=false\n");
 std::vector<fs::path> paths;for(auto&e:fs::recursive_directory_iterator(dst))if(e.is_regular_file())paths.push_back(e.path());std::sort(paths.begin(),paths.end());std::string sums;for(auto&p:paths)sums+=hash(p)+"  "+fs::relative(p,dst).generic_string()+"\n";put(dst/"SHA256SUMS.txt",sums);put(dst/"COMPLETE.txt","sha256_manifest="+hash(dst/"SHA256SUMS.txt")+"\n");std::cout<<"EXPORT_READY: "<<periods<<" decades; incomplete_selected="<<incomplete<<"; production_admitted=false"<<std::endl;return 0;
 }catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<std::endl;return 1;}}
